const productFiles = import.meta.glob('./products/*.webp', { eager: true, import: 'default' });
export const productTiles = Object.keys(productFiles).sort().map((k) => productFiles[k]);

const teamFiles = import.meta.glob('./team/*.webp', { eager: true, import: 'default' });
export const teamPhoto = (slug) => teamFiles[`./team/${slug}.webp`];
